import { chromium } from "playwright";
const B = "http://localhost:3100";
const konten = ["admin", "flaeche", "landwirt", "investor", "anbieter", "unternehmen", "mitglied", "kommune", "gutachter", "bank", "lieferant", "energie-kunde1", "bo-akquise", "bo-projektleitung", "bo-transaktion", "bo-compliance", "bo-buchhaltung", "bo-betrieb", "bo-energie", "bo-lesen"];
const b = await chromium.launch(); const probleme = []; let n = 0;
for (const k of konten) {
  const ctx = await b.newContext({ viewport: { width: 390, height: 844 } });
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email: `${k}@example.com`, passwort: "Demo-2026!" }, headers: { Origin: B } });
  if (!r.ok()) { probleme.push({ k, login: r.status(), body: (await r.text()).slice(0, 200) }); await ctx.close(); continue; }
  const p = await ctx.newPage();
  await p.goto(B + "/portal", { waitUntil: "load", timeout: 180000 });
  const start = await p.evaluate(() => [...new Set([...document.querySelectorAll("a[href^='/portal']")].map((a) => a.getAttribute("href")))]);
  const besucht = new Set(); const queue = ["/portal", ...start];
  while (queue.length && besucht.size < 40) {
    const pfad = queue.shift(); if (besucht.has(pfad)) continue; besucht.add(pfad);
    const q = await ctx.newPage(); const f = [];
    q.on("pageerror", (e) => f.push(e.message.slice(0, 150)));
    q.on("console", (m) => m.type() === "error" && !/hydrat/i.test(m.text()) && f.push(m.text().slice(0, 150)));
    let res = null, info = { w: 0, iw: 390, l: [] };
    for (let v = 0; v < 2 && !res; v++) {
      try { res = await q.goto(B + pfad, { waitUntil: "load", timeout: 180000 }); } catch (e) { if (v) f.push("GOTO " + e.message.slice(0, 80)); }
    }
    await q.waitForTimeout(300);
    try { info = await q.evaluate(() => ({ w: document.documentElement.scrollWidth, iw: innerWidth, l: [...document.querySelectorAll("a[href^='/portal']")].map((a) => a.getAttribute("href")) })); } catch (e) { f.push("EVAL " + e.message.slice(0, 80)); }
    info.l.forEach((x) => !besucht.has(x) && queue.push(x));
    n++;
    if (!res || res.status() !== 200 || f.length || info.w > info.iw + 1) probleme.push({ k, pfad, st: res ? res.status() : 0, w: info.w, f });
    await q.close();
  }
  console.log(k, "Seiten:", besucht.size);
  await ctx.close();
}
console.log("gesamt", n, JSON.stringify(probleme, null, 1));
await b.close();
