import { chromium } from "playwright";
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  for (const k of ["bo-buchhaltung", "admin", "bo-betrieb"]) {
    const ctx = await b.newContext({ viewport: { width: 390, height: 844 } });
    await ctx.request.post(B + "/api/auth/login", { data: { email: `${k}@example.com`, passwort: "Demo-2026!" }, headers: { Origin: B } });
    const p = await ctx.newPage(); const f = [];
    p.on("console", (m) => m.type() === "error" && f.push(m.text()));
    await p.goto(B + "/portal/admin/anlagen", { waitUntil: "load", timeout: 180000 }); await p.waitForTimeout(1500);
    console.log("==", k, f.length ? f.map((x) => x.slice(0, 2500)).join("\n---\n") : "ok");
    await ctx.close();
  }
} finally { await b.close(); }
