// Prüfteam 3: Portal-Durchlauf je Konto – Konsole (inkl. Hydration), Überlauf 390 px, A11y-Grundlagen
import { chromium } from "playwright";
const B = "http://localhost:3100";
const konten = (process.argv[2] || "admin,investor,flaeche,bo-energie,gutachter,bank").split(",");
const MAX = Number(process.argv[3] || 45);
const b = await chromium.launch();
const probleme = [];
const a11ySammel = new Map();
try {
  for (const k of konten) {
    const ctx = await b.newContext({ viewport: { width: 390, height: 844 } });
    const r = await ctx.request.post(B + "/api/auth/login", { data: { email: `${k}@example.com`, passwort: "Demo-2026!" }, headers: { Origin: B } });
    if (!r.ok()) { probleme.push({ k, login: r.status() }); await ctx.close(); continue; }
    const besucht = new Set(); const queue = ["/portal"];
    const q = await ctx.newPage();
    let f = [];
    q.on("pageerror", (e) => f.push("PAGEERR " + e.message.slice(0, 300)));
    q.on("console", (m) => (m.type() === "error" || (m.type() === "warning" && /key|hydrat|React/i.test(m.text()))) && f.push(m.type() + ": " + m.text().slice(0, 400)));
    while (queue.length && besucht.size < MAX) {
      const pfad = queue.shift(); if (besucht.has(pfad)) continue; besucht.add(pfad);
      f = [];
      let res = null, info = { w: 0, iw: 390, l: [], a11y: [], breit: [] };
      try { res = await q.goto(B + pfad, { waitUntil: "load", timeout: 180000 }); } catch (e) { f.push("GOTO " + e.message.slice(0, 80)); }
      await q.waitForTimeout(700);
      try {
        info = await q.evaluate(() => {
          const name = (el) => (el.getAttribute("aria-label") || el.getAttribute("aria-labelledby") || el.getAttribute("title") || el.textContent || "").trim();
          const a11y = [];
          for (const el of document.querySelectorAll("button, a[href]")) if (!name(el) && !el.querySelector("img[alt]:not([alt=''])")) a11y.push(`${el.tagName.toLowerCase()} ohne Namen: ${el.outerHTML.slice(0, 140)}`);
          for (const el of document.querySelectorAll("input:not([type=hidden]):not([type=submit]):not([type=button]), select, textarea")) {
            const ok = el.getAttribute("aria-label") || el.getAttribute("aria-labelledby") || el.closest("label") || (el.id && document.querySelector(`label[for="${CSS.escape(el.id)}"]`)) || el.getAttribute("title");
            if (!ok) a11y.push(`${el.tagName.toLowerCase()} ohne Label: ${el.outerHTML.slice(0, 160)}`);
          }
          const iw = innerWidth; const breit = [];
          if (document.documentElement.scrollWidth > iw + 1) for (const el of document.querySelectorAll("body *")) { const r = el.getBoundingClientRect(); if (r.right > iw + 1 && r.width > 0) { let p = el.parentElement, clip = false; while (p && p !== document.body) { const s = getComputedStyle(p); if (/(auto|scroll|hidden|clip)/.test(s.overflowX)) { clip = true; break; } p = p.parentElement; } if (!clip) breit.push(`${el.tagName.toLowerCase()}.${String(el.className).slice(0, 90)} r=${Math.round(r.right)}`); } if (breit.length > 4) break; }
          return { w: document.documentElement.scrollWidth, iw, l: [...document.querySelectorAll("a[href^='/portal']")].map((a) => a.getAttribute("href").split("#")[0]), a11y, breit };
        });
      } catch (e) { f.push("EVAL " + e.message.slice(0, 80)); }
      info.l.forEach((x) => !besucht.has(x) && !queue.includes(x) && !/\/api\//.test(x) && queue.push(x));
      const st = res ? res.status() : 0;
      if (st !== 200 || f.length || info.w > info.iw + 1) probleme.push({ k, pfad, st, w: info.w, f, breit: info.breit });
      for (const x of info.a11y) { const key = x.replace(/id="[^"]*"/g, ""); if (!a11ySammel.has(key)) a11ySammel.set(key, `${k} ${pfad}`); }
    }
    console.log(k, "Seiten:", besucht.size);
    await ctx.close();
  }
} finally { await b.close(); }
console.log("PROBLEME", JSON.stringify(probleme, null, 1));
console.log("A11Y", a11ySammel.size); for (const [x, wo] of a11ySammel) console.log(" -", wo, "|", x);

